 // Convert to lowercase and sort\n        processed = map(non_empty, to_lowercase)\n        sorted_lines = sort(processed)\n        result = join(sorted_lines, "\\n")\n\n        output_filename = "processed_" + filename\n        write_file(output_filename, result)\n        print("File processed successfully: " + output_filename)\n\n        return true\n    catch (error):\n        print("Error processing file: " + str(error))\n        return false\n    end\nend\n\nfun main():\n    success = process_text_file("data.txt")\n    if (success) then:\n        print("Text processing completed")\n    else:\n        print("Text processing failed")\n    end\nend\n')),(0,a.yg)("h3",{id:"data-analysis-example"},"Data Analysis Example"),(0,a.yg)("pre",null,(0,a.yg)("code",{parentName:"pre",className:"language-uddin"},'fun is_positive(num):\n    return num > 0\nend\n\nfun square(num):\n    return num * num\nend\n\nfun add(a, b):\n    return a + b\nend\n\nfun analyze_numbers(data):\n    // Filter positive numbers\n    positives = filter(data, is_positive)\n\n    // Calculate squares\n    squares = map(positives, square)\n\n    // Calculate statistics\n    total = reduce(squares, add, 0)\n    count = len(squares)\n    average = total / count\n\n    return {\n        "count": count,\n        "total": total,\n        "average": average,\n        "max": max(squares),\n        "min": min(squares)\n    }\nend\n\nfun main():\n    numbers = [-2, 5, -1, 8, 3, -4, 7]\n    stats = analyze_numbers(numbers)\n\n    print("Analysis Results:")\n    print("Positive numbers processed: " + str(stats["count"]))\n    print("Sum of squares: " + str(stats["total"]))\n    print("Average: " + str(stats["average"]))\nend\n')),(0,a.yg)("p",null,"This comprehensive guide covers the most frequently used built-in functions. For mathematical functions, networking capabilities, and other advanced features, refer to the subsequent chapters in this documentation."))}p.isMDXComponent=!0},5680:(e,n,t)=>{t.d(n,{xA:()=